bool TimeCodedMotionChannelClass::Load_W3D(ChunkLoadClass &cload)
{
	unsigned long left = cload.Cur_Chunk_Length();
	W3dTimeCodedAnimChannelStruct header;
	left -= sizeof(header);
	if (cload.Read(&header, sizeof(header)) != sizeof(header)) return false;

	NumTimeCodes = header.NumTimeCodes;
	VectorLen = header.VectorLen;
	Type = header.Flags;
	PivotIdx = header.Pivot;
	PacketSize = VectorLen + 1;
	LastTimeCodeIdx = (NumTimeCodes - 1) * PacketSize;

	// What remains of the chunk is the packet data after the first word, which the header carried.
	Data = new unsigned long[left / 4 + 1];
	Data[0] = header.Data[0];
	if (cload.Read(&Data[1], left) != left) {
		delete[] Data;
		Data = 0;
		return false;
	}
	return true;
}

