// FUNCTION: BFME2 0x00195EF0 size=107 name=?Get_Bit@TimeCodedBitChannelClass@@QAEHH@Z evidence=N:ledger tier=B hypothesis:Z
int TimeCodedBitChannelClass::Get_Bit(int frame)
{
	int index = 0;
	if (frame >= (int)(Bits[CachedIdx] & 0x7FFFFFFF)) {
		index = CachedIdx + 1;
	}
	while (index < NumTimeCodes) {
		if (frame < (int)(Bits[index] & 0x7FFFFFFF)) break;
		index++;
	}
	index--;
	if (index < 0) {
		index = 0;
	}
	CachedIdx = index;
	return (Bits[index] & 0x80000000) == 0x80000000;
}

