	PivotIdx    = chan.Pivot;
	NumFrames	= chan.NumFrames;
	Scale			= chan.Scale;

	Data = new unsigned char[numInts * sizeof(unsigned long) + sizeof(unsigned long)];
	DeltaBytes = numInts * sizeof(unsigned long);
